"""Authored teaching sequences. Not generated from paragraph splitting."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
def N(id,label,state=''):return dict(id=id,label=label,state=state)
def P(a,b,label='',delay=0):return dict(type='send',from_=a,to=b,label=label,delay=delay)
def D(a,b,delay=0):return dict(type='send',from_=a,to=b,label='',delay=delay,kind='dot')
def S(n,text,color='accent',delay=0):return dict(type='state',node=n,text=text,color=color,delay=delay)
def W(n,duration=5,delay=0):return dict(type='work',node=n,duration=duration,delay=delay)
def B(a,b,*actions):
 for x in actions:
  if 'from_' in x:x['from']=x.pop('from_')
 return dict(lines=[a,b],actions=list(actions))
def L(title,nodes,intro,takeaway,*beats):
 for i,b in enumerate(beats):b['time']=i*7
 return dict(title=title,nodes=nodes,intro=intro,takeaway=takeaway,duration=len(beats)*7,beats=list(beats))
def save(key,lessons):
 folder=ROOT/f'video/{key}/sequence';folder.mkdir(parents=True,exist_ok=True)
 concept=json.loads((ROOT/f'content/concepts/{key}.json').read_text())
 (folder/'storyboard.json').write_text(json.dumps(dict(concept=key,authored='2026-10-20',sources=concept['sources'],lessons=lessons),indent=2)+'\n')

